{"file_path":"src/diff.js","content":"/**
 * Longest common subsequence over whole lines, compared as exact strings, and
 * the changes it leaves behind.
 */

/**
 * Suffix table of longest common subsequence lengths: table[i][j] is the length
 * of the longest common subsequence of a.slice(i) and b.slice(j).
 */
function suffixLengths(a, b) {
  const n = a.length
  const m = b.length
  const table = new Array(n + 1)
  for (let i = 0; i <= n; i += 1) table[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i -= 1) {
    const row = table[i]
    const next = table[i + 1]
    for (let j = m - 1; j >= 0; j -= 1) {
      row[j] = a[i] === b[j] ? next[j + 1] + 1 : Math.max(next[j], row[j + 1])
    }
  }
  return table
}

/**
 * The matched pairs of the earliest longest common subsequence of base and
 * side. Walking from the start, a match is taken whenever the two current lines
 * are equal; otherwise the side whose remaining subsequence is at least as long
 * advances, with the base preferred when they tie.
 */
export function commonSubsequence(base, side) {
  const table = suffixLengths(base, side)
  const matches = []
  let i = 0
  let j = 0
  while (i < base.length && j < side.length) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i += 1
      j += 1
    } else if (table[i + 1][j] >= table[i][j + 1]) {
      i += 1
    } else {
      j += 1
    }
  }
  return matches
}

/**
 * The stretches the common subsequence does not cover, each a run of base lines
 * (half open, baseStart to baseEnd) replaced by a run of side lines (half open,
 * sideStart to sideEnd).
 */
export function changes(base, side) {
  const result = []
  let i = 0
  let j = 0
  const push = (baseEnd, sideEnd) => {
    if (baseEnd > i || sideEnd > j) {
      result.push({ baseStart: i, baseEnd, sideStart: j, sideEnd })
    }
  }
  for (const [bi, sj] of commonSubsequence(base, side)) {
    push(bi, sj)
    i = bi + 1
    j = sj + 1
  }
  push(base.length, side.length)
  return result
}
"}

