{"file_path":"src/merge.js","content":"/**
 * The three way merge itself: the regions of the base the two sides leave
 * alone or change, and how each changed region resolves.
 */

import { changes } from './diff.js'

/**
 * The regions of the merge, in order. A stable region carries the base lines it
 * keeps unchanged; a changed region carries the lines each of the three
 * documents holds for it.
 */
export function regionsOf(mine, base, theirs) {
  const mineChanges = changes(base, mine).map(change => ({ ...change, side: 'mine' }))
  const theirChanges = changes(base, theirs).map(change => ({ ...change, side: 'theirs' }))
  const all = [...mineChanges, ...theirChanges]
  all.sort((left, right) => left.baseStart - right.baseStart)

  const regions = []
  let done = 0
  let at = 0
  while (at < all.length) {
    const group = [all[at]]
    let start = all[at].baseStart
    let end = all[at].baseEnd
    at += 1
    while (at < all.length && all[at].baseStart <= end) {
      end = Math.max(end, all[at].baseEnd)
      group.push(all[at])
      at += 1
    }
    if (start > done) regions.push({ kind: 'stable', lines: base.slice(done, start) })
    regions.push({
      kind: 'changed',
      mine: sideLines(group, 'mine', mine, base, start, end),
      base: base.slice(start, end),
      theirs: sideLines(group, 'theirs', theirs, base, start, end),
    })
    done = end
  }
  if (done < base.length) regions.push({ kind: 'stable', lines: base.slice(done) })
  return regions
}

/**
 * What one side holds for a region: the base lines when that side changed
 * nothing there, and otherwise its own lines, stretched at both ends by however
 * far the region reaches past that side's own changes.
 */
function sideLines(group, side, document, base, start, end) {
  const own = group.filter(change => change.side === side)
  if (own.length === 0) return base.slice(start, end)
  let low = Infinity
  let high = -Infinity
  for (const change of own) {
    if (change.baseStart < low) {
      low = change.baseStart
      var lowSide = change.sideStart // eslint-disable-line no-var
    }
    if (change.baseEnd > high) {
      high = change.baseEnd
      var highSide = change.sideEnd // eslint-disable-line no-var
    }
  }
  return document.slice(lowSide - (low - start), highSide + (end - high))
}

const same = (left, right) => left.length === right.length && left.every((line, index) => line === right[index])

/**
 * How a changed region resolves: `both`, `mine`, `theirs` or `conflict`, with
 * the lines the merge takes when it is not a conflict.
 */
export function resolve(region) {
  if (same(region.mine, region.theirs)) return { kind: 'both', lines: region.mine }
  if (same(region.mine, region.base)) return { kind: 'theirs', lines: region.theirs }
  if (same(region.theirs, region.base)) return { kind: 'mine', lines: region.mine }
  return { kind: 'conflict' }
}
"}

